// clean tidies user-typed text: trims it, squashes inner whitespace and lowercases it.
function clean(s) {
  return String(s).trim().replace(/\s+/g, ' ').toLowerCase();
}

module.exports = { clean };

const { clean } = require('./clean');

// makeHandle builds the URL handle for a user: "Ada Lovelace" -> "ada-lovelace".
function makeHandle(name) {
  return clean(name).replace(/ /g, '-');
}

module.exports = { makeHandle };

const { clean } = require('./clean');

// findUsers returns the users whose name contains the query, ignoring case and extra spaces.
function findUsers(users, query) {
  const q = clean(query);
  return users.filter((u) => clean(u.name).includes(q));
}

module.exports = { findUsers };
